def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    if "ERPNext" in json.dumps({"l": lessons, "q": questions}):
        problems.append(f"  {name}: ERPNext branding leakage")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.161.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.160.0"' not in init:
        sys.exit("ABORT: not at v3.160.0.")
    for k in ("close_statements", "advanced_accounts"):
        if k not in data:
            sys.exit(f"ABORT: {k} module not found in data file.")

    problems = _validate("ACC7", LESSONS_A7, QUESTIONS_A7, 9) + _validate("ACC8", LESSONS_A8, QUESTIONS_A8, 9)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    for name, lessons, questions, key, desc in (
        ("ACC 7", LESSONS_A7, QUESTIONS_A7, "close_statements",
         "The period close and the financial statements: the monthly close with its nine-line checklist and day-five target, cut-off and the completeness pairs, reading the P&L (four rules, pre-reading checks), the balance sheet's line-by-line checks with the equity rule, the cash flow statement's three sections and four-question read, fixed assets and depreciation with the capitalisation policy and annual verification, and year-end as the twelfth close plus annual mechanics."),
        ("ACC 8", LESSONS_A8, QUESTIONS_A8, "advanced_accounts",
         "The structural layer: the Accounts Settings walk, fiscal years and the companies-follow-legal-reality rule with inter-company disciplines, the four finance authorities and the permission matrix, the consolidated finance calendar, the handover and absence tests, the assembled control system with the pairing principle and the CSA, and the professional boundaries between the system role, the accountant, the tax adviser, and the auditor — closing with the track's eight laws."),
    ):
        bank = rebalance(list(questions))
        dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
        if max(dist.values()) > 10:
            print(f"ABORT — {name} spread failed: {dist}")
            sys.exit(1)
        total = sum(len(l["html"]) for l in lessons)
        print(f"{name} v2.2: {len(lessons)} chapters ({total:,} chars, min {min(len(l['html']) for l in lessons):,}), bank {len(bank)}, spread {dist}")
        if not CHECK_ONLY:
            data[key]["lessons"] = lessons
            data[key]["questions"] = bank
            data[key]["desc"] = desc

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.160.0"', '"3.161.0"'))
    print("  data: ACCOUNTS 7 + 8 lessons + banks REPLACED (style v2.2) — Accounts track COMPLETE")
    print("wrote __version__ -> 3.161.0")


if __name__ == "__main__":
    main()
